import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"50、【鼎】 巽下离上","description":"周易口诀义 - 50、【鼎】 巽下离上","frontmatter":{"title":"50、【鼎】 巽下离上","description":"周易口诀义 - 50、【鼎】 巽下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/052.md","filePath":"zh/classics/koujueyi/052.md"}'),r={name:"zh/classics/koujueyi/052.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_50、【鼎】-巽下离上" tabindex="-1">50、【鼎】 巽下离上 <a class="header-anchor" href="#_50、【鼎】-巽下离上" aria-label="Permalink to “50、【鼎】 巽下离上”">​</a></h1><p>彖曰：鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以「元亨」。</p><p>象曰：木上有火，「鼎」，君子以正位凝命。</p><p>初六：鼎颠趾，利出否。得妾以其子，无咎。</p><p>象曰：「鼎颠趾」，未悖也；「利出否」，以从贵也。</p><p>九二：鼎有实，我仇有疾，不我能即，吉。</p><p>象曰：「鼎有实」，慎所之也；「我仇有疾」，终无尤也。</p><p>九三：鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。</p><p>象曰：「鼎耳革」，失其义也。</p><p>九四：鼎折足，覆公𫗧，其形渥，凶。</p><p>象曰：「覆公𫗧」，信如何也！</p><p>六五：鼎黄耳金铉，利贞。</p><p>象曰：「鼎黄耳」，中以为实也。</p><p>上九：鼎玉铉，大吉，无不利。</p><p>象曰：玉铉在上，刚柔节也。</p><p>解读</p><p>「鼎元吉亨」者，鼎者器象之名，故何妥云：「古者铸金为此器，能调五味，变故取新，以成烹饪之用，以供宗庙，次养圣贤。」天子以天下为鼎，诸侯以国为鼎，变故成新，尤须当理，故先元吉，后乃亨通，故曰「元吉亨」也。象曰「木上有火，鼎」者，「巽」木也，又为入，「离」，火也。木入火中，是烹饪，鼎之象也。「君子以正位凝命」者，凝，严整也。鼎既变故成新，所以君子象之，正定尊卑之位，使其有别；布示严凝之命，使其不妄轻犯也。</p><p>初六，「鼎颠趾，利出否，得妾以其子，无咎」者，趾，足也；颠，倒也。「鼎」之为义，下实上虚，虚以纳物，实以受物也。今初六以阴处下，即是鼎口向下，鼎足倒上，即是鼎倾覆，足倒在上，故曰「鼎颠趾」也。鼎既「颠趾」，其所利者，利在倾弃鄙秽之物，故曰「利出否也」。以事明之，亦犹正室虽亡，媵妾不可为室主。若以妾为室主，亦犹鼎之颠趾，咎莫大焉。妾若有子，即母以子贵，以此继室，犹可免咎，故曰「得妾以其子，无咎」也。</p><p>「九二，鼎有实，我仇有疾，不我能即，吉」者，实为阳也，即，就也。鼎之为义，虚中待物，乃是其常。今九二以阳居中，失虚中之义，施之人事，即是志意盈满，不受规诲，故曰「鼎有实」也。「我仇」谓五也；仇，匹也。然六五是我之仇匹，有乘刚之疾，不得来就于我，为六五下有二刚爻，为疾也。我得全其志，不为骄盈，即获吉也，故曰「我仇有疾，不我能即，吉」也。</p><p>「九三，鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉」者，鼎之为义，下实上虚。九三既处下卦之上，即是鼎耳。「鼎耳」之用，唯在虚空，以待铉而举之。今九三以阳处之，而自实塞，即是变革鼎耳之常道也，故曰「鼎耳革」。以人事明之，是怀小人之行而自实塞，不纳贤良，故曰「其行塞」也。既无虚中待物之心，物亦不来归己，犹之雉膏美物而终不得食，故曰「雉膏不食」也。「方雨亏悔，终吉」者，此戒其勿行刚处亢，以柔和为用，若不全任刚亢，务在和通，方欲为此和通，即亏减其悔，终获吉矣。雨，喻阴阳和顺也。</p><p>「九四，鼎折足，覆公𫗧，其形渥，凶」者，𫗧是八珍糁鼎之实也；渥，沾濡之貌。九四应在初，初已倾弃秽物，即九四有以受其珍美之物也。九四上近于五，即有承五之心，下又应初，又有施下之义，既承且施，力所不任，即致折足而倾弃其𫗧，故曰「鼎折足，覆公𫗧」。鼎足既折，覆于地，即被沙卤沾濡，喻之于人智小谋大，力小任重，受其至辱，灾及其身，故曰「其形渥，凶」。</p><p>「六五：鼎黄耳金铉，利贞。」者，黄中，谓五也；金刚，谓二也；铉者，扛鼎之物也。六五以柔居中，故曰「黄耳」。应在九二，以柔纳刚，纳金铉而以举之，故曰「金铉」也。所纳刚正，不为虚妄，故曰「利贞」。</p><p>「上九：鼎玉铉，大吉，无不利」者，坚刚之物而怀润泽之性，喻道大成而有斯美，体刚履柔，是用玉铉而以自举，故曰「鼎玉铉」也。应不在下，不私其用，故获大吉而无不利，故曰「大吉，无不利」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
